// Package strutil is a vendored third-party helper.
func PadLeft(s string, width int) string {
	for len(s) < width {
		s = " " + s
	}
	return s
}

package stats

type Point struct {
	X, Y float64
}

func (p Point) String() string {
	return fmt.Sprintf("(%g, %g)", p.X, p.Y)
}

// sumPositive adds the positive values.
func sumPositive(values []int)   int {   // total of positives
    total := 0
    for _, v := range values {   // each value
        if v > 0 { total += v
        }
    }
    return total
}

